import{_ as i,a0 as l,w as p,s,ao as d,I as a,x as r,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"用浏览器管理 Docker | LCTT x X-CMD","titleTemplate":false,"description":"用浏览器管理 Docker | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用浏览器管理 Docker | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用浏览器管理 Docker | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 How to Setup DockerUI--a Web Interface for Docker","title":"用浏览器管理 Docker","tag":"201511","desc":""},"relativePath":"201511/20151012 How to Setup DockerUI--a Web Interface for Docker.md","filePath":"[post].md"}'),c={name:"201511/20151012 How to Setup DockerUI--a Web Interface for Docker.md"};function k(u,e,h,m,b,x){const o=l("Link");return p(),s("div",null,[e[24]||(e[24]=d(`<h1 id="用浏览器管理-docker" tabindex="-1">用浏览器管理 Docker <a class="header-anchor" href="#用浏览器管理-docker" aria-label="Permalink to “用浏览器管理 Docker”">​</a></h1><p>Docker 越来越流行了。在一个容器里面而不是虚拟机里运行一个完整的操作系统是一种非常棒的技术和想法。docker 已经通过节省工作时间来拯救了成千上万的系统管理员和开发人员。这是一个开源技术，提供一个平台来把应用程序当作容器来打包、分发、共享和运行，而不用关注主机上运行的操作系统是什么。它没有开发语言、框架或打包系统的限制，并且可以在任何时间、任何地点运行，从小型计算机到高端服务器都可以。运行 docker 容器和管理它们可能会花费一点点努力和时间，所以现在有一款基于 web 的应用程序－DockerUI，可以让管理和运行容器变得很简单。DockerUI 是一个对那些不熟悉 Linux 命令行，但又很想运行容器化程序的人很有帮助的工具。DockerUI 是一个开源的基于 web 的应用程序，它最值得称道的是它华丽的设计和用来运行和管理 docker 的简洁的操作界面。</p><p>下面会介绍如何在 Linux 上安装配置 DockerUI。</p><h3 id="_1-安装-docker" tabindex="-1">1. 安装 docker <a class="header-anchor" href="#_1-安装-docker" aria-label="Permalink to “1. 安装 docker”">​</a></h3><p>首先，我们需要安装 docker。我们得感谢 docker 的开发者，让我们可以简单的在主流 linux 发行版上安装 docker。为了安装 docker，我们得在对应的发行版上使用下面的命令。</p><h4 id="ubuntu-fedora-centos-rhel-debian" tabindex="-1">Ubuntu/Fedora/CentOS/RHEL/Debian <a class="header-anchor" href="#ubuntu-fedora-centos-rhel-debian" aria-label="Permalink to “Ubuntu/Fedora/CentOS/RHEL/Debian”">​</a></h4><p>docker 维护者已经写了一个非常棒的脚本，用它可以在 Ubuntu 15.04/14.10/14.04、 CentOS 6.x/7、 Fedora 22、 RHEL 7 和 Debian 8.x 这几个 linux 发行版上安装 docker。这个脚本可以识别出我们的机器上运行的 linux 的发行版本，然后将需要的源库添加到文件系统、并更新本地的安装源目录，最后安装 docker 及其依赖库。要使用这个脚本安装docker，我们需要在 root 用户或者 sudo 权限下运行如下的命令，</p><pre><code># curl -sSL https://get.docker.com/ | sh
</code></pre><h4 id="opensuse-suse-linux-企业版" tabindex="-1">OpenSuse/SUSE Linux 企业版 <a class="header-anchor" href="#opensuse-suse-linux-企业版" aria-label="Permalink to “OpenSuse/SUSE Linux 企业版”">​</a></h4><p>要在运行了 OpenSuse 13.1/13.2 或者 SUSE Linux Enterprise Server 12 的机器上安装 docker，我们只需要简单的执行zypper 命令。运行下面的命令就可以安装最新版本的docker：</p><pre><code># zypper in docker
</code></pre><h4 id="archlinux" tabindex="-1">ArchLinux <a class="header-anchor" href="#archlinux" aria-label="Permalink to “ArchLinux”">​</a></h4><p>docker 在 ArchLinux 的官方源和社区维护的 AUR 库中可以找到。所以在 ArchLinux 上我们有两种方式来安装 docker。使用官方源安装，需要执行下面的 pacman 命令：</p><pre><code># pacman -S docker
</code></pre><p>如果要从社区源 AUR 安装 docker，需要执行下面的命令：</p><pre><code># yaourt -S docker-git
</code></pre><h3 id="_2-启动" tabindex="-1">2. 启动 <a class="header-anchor" href="#_2-启动" aria-label="Permalink to “2. 启动”">​</a></h3><p>安装好 docker 之后，我们需要运行 docker 守护进程，然后才能运行并管理 docker 容器。我们需要使用下列命令来确认 docker 守护进程已经安装并运行了。</p><h4 id="在-sysvinit-上" tabindex="-1">在 SysVinit 上#### <a class="header-anchor" href="#在-sysvinit-上" aria-label="Permalink to “在 SysVinit 上####”">​</a></h4><pre><code># service docker start
</code></pre><h4 id="在systemd-上" tabindex="-1">在Systemd 上#### <a class="header-anchor" href="#在systemd-上" aria-label="Permalink to “在Systemd 上####”">​</a></h4><pre><code># systemctl start docker
</code></pre><h3 id="_3-安装-dockerui" tabindex="-1">3. 安装 DockerUI <a class="header-anchor" href="#_3-安装-dockerui" aria-label="Permalink to “3. 安装 DockerUI”">​</a></h3><p>安装 DockerUI 比安装 docker 要简单很多。我们仅仅需要从 docker 注册库上拉取 dockerui ，然后在容器里面运行。要完成这些，我们只需要简单的执行下面的命令：</p><pre><code># docker run -d -p 9000:9000 --privileged -v /var/run/docker.sock:/var/run/docker.sock dockerui/dockerui
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/starting-dockerui-container.png" alt="Starting DockerUI Container"></p><p>在上面的命令里，dockerui 使用的默认端口是9000，我们需要使用<code>-p</code> 命令映射默认端口。使用<code>-v</code> 标志我们可以指定docker 的 socket。如果主机使用了 SELinux 那么就得使用<code>--privileged</code> 标志。</p><p>执行完上面的命令后，我们要检查 DockerUI 容器是否运行了，或者使用下面的命令检查：</p><pre><code># docker ps
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/running-docker-containers.png" alt="Running Docker Containers"></p><h3 id="_4-拉取-docker-镜像" tabindex="-1">4. 拉取 docker 镜像 <a class="header-anchor" href="#_4-拉取-docker-镜像" aria-label="Permalink to “4. 拉取 docker 镜像”">​</a></h3><p>现在我们还不能直接使用 DockerUI 拉取镜像，所以我们需要在命令行下拉取 docker 镜像。要完成这些我们需要执行下面的命令。</p><pre><code># docker pull ubuntu
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/docker-image-pull.png" alt="Docker Image Pull"></p>`,34)),a("p",null,[e[1]||(e[1]=r("上面的命令将会从 docker 官方源 ",-1)),t(o,{href:"https://hub.docker.com/"},{default:n(()=>[...e[0]||(e[0]=[r("Docker Hub",-1)])]),_:1}),e[2]||(e[2]=r("拉取一个标志为 ubuntu 的镜像。类似的我们可以从 Hub 拉取需要的其它镜像。",-1))]),e[25]||(e[25]=a("h3",{id:"_4-管理",tabindex:"-1"},[r("4. 管理 "),a("a",{class:"header-anchor",href:"#_4-管理","aria-label":"Permalink to “4. 管理”"},"​")],-1)),e[26]||(e[26]=a("p",null,"启动了 DockerUI 容器之后，我们可以用它来执行启动、暂停、终止、删除以及 DockerUI 提供的其它操作 docker 容器的命令。",-1)),a("p",null,[e[5]||(e[5]=r("首先，我们需要在 web 浏览器里面打开 dockerui：在浏览器里面输入 ",-1)),t(o,{href:"http://ip-address:9000"},{default:n(()=>[...e[3]||(e[3]=[r("http://ip-address:9000",-1)])]),_:1}),e[6]||(e[6]=r(" 或者 ",-1)),t(o,{href:"http://mydomain.com:9000"},{default:n(()=>[...e[4]||(e[4]=[r("http://mydomain.com:9000",-1)])]),_:1}),e[7]||(e[7]=r("，具体要根据你的系统配置。默认情况下登录不需要认证，但是可以配置我们的 web 服务器来要求登录认证。要启动一个容器，我们需要有包含我们要运行的程序的镜像。",-1))]),e[27]||(e[27]=d('<h4 id="创建" tabindex="-1">创建 <a class="header-anchor" href="#创建" aria-label="Permalink to “创建”">​</a></h4><p>创建容器我们需要在 Images 页面里，点击我们想创建的容器的镜像 id。然后点击 <code>Create</code> 按钮，接下来我们就会被要求输入创建容器所需要的属性。这些都完成之后，我们需要点击按钮<code>Create</code> 完成最终的创建。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/creating-docker-container.png" alt="Creating Docker Container"></p><h4 id="停止" tabindex="-1">停止 <a class="header-anchor" href="#停止" aria-label="Permalink to “停止”">​</a></h4><p>要停止一个容器，我们只需要跳转到<code>Containers</code> 页面，然后选取要停止的容器。然后在 Action 的子菜单里面按下 Stop 就行了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/managing-container.png" alt="Managing Container"></p><h4 id="暂停与恢复" tabindex="-1">暂停与恢复 <a class="header-anchor" href="#暂停与恢复" aria-label="Permalink to “暂停与恢复”">​</a></h4><p>要暂停一个容器，只需要简单的选取目标容器，然后点击 Pause 就行了。恢复一个容器只需要在 Actions 的子菜单里面点击 Unpause 就行了。</p><h4 id="删除" tabindex="-1">删除 <a class="header-anchor" href="#删除" aria-label="Permalink to “删除”">​</a></h4><p>类似于我们上面完成的任务，杀掉或者删除一个容器或镜像也是很简单的。只需要检查、选择容器或镜像，然后点击 Kill 或者 Remove 就行了。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3>',11)),a("p",null,[e[9]||(e[9]=r("DockerUI 使用了 docker 远程 API 提供了一个很棒的管理 docker 容器的 web 界面。它的开发者们完全使用 HTML 和 JS 设计、开发了这个应用。目前这个程序还处于开发中，并且还有大量的工作要完成，所以我们并不推荐将它应用在生产环境。它可以帮助用户简单的完成管理容器和镜像，而且只需要一点点工作。如果想要为 DockerUI 做贡献，可以访问它们的 ",-1)),t(o,{href:"https://github.com/crosbymichael/dockerui/"},{default:n(()=>[...e[8]||(e[8]=[r("Github 仓库",-1)])]),_:1}),e[10]||(e[10]=r("。如果有问题、建议、反馈，请写在下面的评论框，这样我们就可以修改或者更新我们的内容。谢谢。",-1))]),e[28]||(e[28]=a("hr",null,null,-1)),a("p",null,[e[12]||(e[12]=r("via: ",-1)),t(o,{href:"http://linoxide.com/linux-how-to/setup-dockerui-web-interface-docker/"},{default:n(()=>[...e[11]||(e[11]=[r("http://linoxide.com/linux-how-to/setup-dockerui-web-interface-docker/",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=r("作者：",-1)),t(o,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[13]||(e[13]=[r("Arun Pyasi",-1)])]),_:1}),e[17]||(e[17]=r(" 译者：",-1)),t(o,{href:"https://github.com/oska874"},{default:n(()=>[...e[14]||(e[14]=[r("oska874",-1)])]),_:1}),e[18]||(e[18]=r(" 校对：",-1)),t(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[15]||(e[15]=[r("wxy",-1)])]),_:1})]),a("p",null,[e[21]||(e[21]=r("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[19]||(e[19]=[r("LCTT",-1)])]),_:1}),e[22]||(e[22]=r(" 原创编译，",-1)),t(o,{href:"https://linux.cn/"},{default:n(()=>[...e[20]||(e[20]=[r("Linux中国",-1)])]),_:1}),e[23]||(e[23]=r(" 荣誉推出",-1))])])}const S=i(c,[["render",k]]);export{g as __pageData,S as default};
